WITH Base AS (SELECT *, credit_limit * age AS credit_limit_times_age FROM customers WHERE signup_date BETWEEN '2024-05-13' AND '2025-01-01'), Agg AS (SELECT YEAR(signup_date) AS signup_year, COUNT(CASE WHEN city = 'Bangkok' THEN 1 END) AS bangkok_count FROM Base GROUP BY YEAR(signup_date)) SELECT signup_year, bangkok_count FROM Agg WHERE bangkok_count < 8 ORDER BY bangkok_count DESC, signup_year LIMIT 1
